import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`roi-calculator`,heroCta:`Get Started`,heroTitle:`Build your ROI calculator in minutes`,heroSubtitle:`Perplexity Computer analyzes your product, models cost savings and revenue impact, and delivers a branded interactive ROI tool - automatically.`,inputUrlCta:`Build my calculator`,inputUrlPlaceholder:`yourproduct.com`,inputUrlPrefill:`Go to {url} and do a deep analysis of this product - extract the pricing model, key features, value propositions, target buyer persona, and competitive positioning. Then build me an interactive ROI calculator as a custom web app deployed to a live URL. The calculator should: (1) Let prospects input their current costs - headcount, tools, time spent on manual processes, and existing vendor spend. (2) Model time savings, cost reduction, and revenue impact based on the product's actual pricing and capabilities. (3) Quantify the total value of switching with a clear payback period and 12-month ROI projection. (4) Include customizable inputs so sales reps can adjust assumptions per deal - average deal size, team size, close rate improvement, and hours saved per week. (5) Generate a polished executive summary slide with the prospect's company name, key ROI metrics, a before/after comparison, and a clear recommendation - formatted for copy-paste into sales decks. (6) Brand the entire tool with colors, logo, and messaging pulled from the website. Save the product profile so future sessions start with the pricing model already loaded.`,heroOverlaySteps:[`Analyzing your product, pricing model, and value propositions`,`Modeling cost savings, time savings, and revenue impact formulas`,`Building a branded interactive ROI calculator with customizable inputs`,`Deploying your ROI tool with executive summary slide - ready to share`],generatingSteps:[`Visiting {url} to extract pricing, features, and competitive positioning`,`Designing an agent to model cost savings, time savings, and revenue impact`,`Building an interactive calculator with customizable deal assumptions`,`Setting up branded executive summary slide and live deployment`],featureSectionTitle:`From product page to deal-closing calculator`,featureCardTitles:[`Connects to your sales stack`,`Outputs you can close with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Pipedrive, Slack, Google Drive, Gmail - Computer pipes ROI data and executive summaries straight into the tools your sales team already uses.`,`Interactive ROI calculator. Customizable deal inputs. 12-month payback projection. Branded executive summary slide. Computer delivers assets that move deals forward.`],capabilitySectionTitle:`Your sales engineer, on autopilot`,capabilitySectionSubtitle:`Paste your product URL, step away, get a deal-ready ROI tool.`,capabilityCards:[{title:`Pricing Model Analysis`,description:`Computer can analyze your product page to extract pricing tiers, feature sets, and value drivers - and translate them into ROI assumptions prospects trust.`},{title:`Interactive Calculator`,description:`Computer can build and deploy a branded web app where prospects input their current costs and instantly see time savings, cost reduction, and payback period.`},{title:`Executive Summary Slide`,description:`Computer can generate a polished one-page ROI summary with before/after metrics, payback timeline, and a clear recommendation - ready for the CFO.`},{title:`Connect Your Tools`,description:`Computer can read from Google Sheets, Pipedrive, Gmail, Slack, and Google Drive - build workflows across your entire sales operation.`},{title:`Knows Your Product`,description:`Computer can remember your pricing model, win/loss data, and past calculator configurations - so every new ROI tool builds on what's already working.`},{title:`Deal Signal Alerts`,description:`Computer can monitor when prospects engage with your ROI calculator - and alert your sales team when a high-value lead runs the numbers.`}]});export{t as default};
